const input = $json;
let context = input.context || {};
if (typeof context === 'string') {
  try { context = JSON.parse(context); } catch (e) { context = {}; }
}
const text = (input.message || '').trim();
const state = input.current_state || 'NEW';

const match = text.toUpperCase().match(/SD-\d{4,}/);
if (match) context.tracking_number = match[0];
context.last_message = text;

let next_state = state;
let reply = '';
let action = 'NONE';

if (state === 'NEW' && !match) {
  next_state = 'AWAITING_TRACKING_NUMBER';
  reply = "I'm sorry to hear that. Could you share the tracking number for the affected delivery, if you have it? (Reply 'skip' if you don't have it.)";
} else {
  action = 'CREATE_ESCALATION';
}

return [{
  json: {
    customer_id: input.customer_id,
    phone: input.phone,
    conversation_id: input.conversation_id || null,
    next_state,
    context,
    reply,
    action
  }
}];

const base = $('Process Problem State').item.json;
return [{
  json: {
    ...base,
    reply: "I'm sorry about that. I've forwarded your report to our operations team" + (base.context.tracking_number ? ` for delivery ${base.context.tracking_number}` : '') + ", and a team member will follow up with you shortly.",
    next_state: 'COMPLETED'
  }
}];

const f = $('Finalize Payload').item.json;
return [{
  json: {
    reply: f.reply,
    next_state: f.next_state,
    customer_id: f.customer_id,
    conversation_id: f.conversation_id
  }
}];
